UPDATE message_recovery
SET state='REPLAYING',next_attempt_at=#{leaseUntil},replay_count=replay_count+1,
    last_replayed_at=#{now},last_replayed_by_type='USER',last_replayed_by_id=#{actorId},
    last_replay_reason=#{reason},last_replay_correlation_id=#{replayCorrelation},lock_version=lock_version+1,
    updated_at=#{now},updated_by_type='USER',updated_by_id=#{actorId}
WHERE tenant_id=#{tenantId} AND recovery_id=#{recoveryId} AND state='OPEN' AND lock_version=#{expectedVersion}

mapper.select:
SELECT recovery_id,direction,source_record_id,business_intent_key,state,attempt_count,next_attempt_at,last_error_code,last_error_summary,dead_lettered_at,recovery_required_at,replay_count,last_replayed_at,last_replayed_by_type,last_replayed_by_id,last_replay_reason,last_replay_correlation_id,resolved_at,lock_version,created_at,updated_at FROM message_recovery WHERE tenant_id=#{tenantId} AND direction='INBOX'
AND direction=#{direction}
AND state=#{state}
AND dead_lettered_at IS NOT NULLAND dead_lettered_at IS NULL
AND last_error_code=#{errorCode}
AND recovery_required_at >= #{from}
AND recovery_required_at <= #{to}
AND (recovery_required_at >  < #{cursorValue} OR (recovery_required_at=#{cursorValue} AND recovery_id >  < #{cursorId})) ORDER BY recovery_required_at ASC DESC,recovery_id ASC DESC LIMIT #{limit}
